CREATE TYPE "PromotionStatus" AS ENUM ('DRAFT', 'ACTIVE', 'DISABLED');
CREATE TYPE "PromotionPlacement" AS ENUM ('HOMEPAGE', 'PRODUCTS', 'SHOPS');
CREATE TYPE "PromotionCtaType" AS ENUM ('PRODUCT', 'SHOP', 'CATEGORY', 'INTERNAL_PATH', 'EXTERNAL_URL');
CREATE TABLE "Promotion" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "subtitle" TEXT, "desktopImageUrl" TEXT NOT NULL, "mobileImageUrl" TEXT, "status" "PromotionStatus" NOT NULL DEFAULT 'DRAFT', "priority" INTEGER NOT NULL DEFAULT 100, "startsAt" TIMESTAMP(3), "endsAt" TIMESTAMP(3), "primaryCtaLabel" TEXT, "primaryCtaType" "PromotionCtaType", "primaryCtaValue" TEXT, "secondaryCtaLabel" TEXT, "secondaryCtaType" "PromotionCtaType", "secondaryCtaValue" TEXT, "placements" "PromotionPlacement"[], "createdByUserId" TEXT NOT NULL, "updatedByUserId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Promotion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FeaturedProduct" ("id" TEXT NOT NULL, "productId" TEXT NOT NULL, "priority" INTEGER NOT NULL DEFAULT 100, "isActive" BOOLEAN NOT NULL DEFAULT true, "startsAt" TIMESTAMP(3), "endsAt" TIMESTAMP(3), "createdByUserId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FeaturedProduct_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FeaturedShop" ("id" TEXT NOT NULL, "vendorId" TEXT NOT NULL, "priority" INTEGER NOT NULL DEFAULT 100, "isActive" BOOLEAN NOT NULL DEFAULT true, "startsAt" TIMESTAMP(3), "endsAt" TIMESTAMP(3), "createdByUserId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FeaturedShop_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "FeaturedProduct_productId_key" ON "FeaturedProduct"("productId");
CREATE UNIQUE INDEX "FeaturedShop_vendorId_key" ON "FeaturedShop"("vendorId");
ALTER TABLE "FeaturedProduct" ADD CONSTRAINT "FeaturedProduct_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "FeaturedShop" ADD CONSTRAINT "FeaturedShop_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "VendorProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE;
